-- Seeds one official community post per app recipe (author_id = null,
-- displayed as "Tarifim Mutfağı" in the UI) so the Topluluk feed always
-- has real content instead of starting empty. Safe to re-run: upserts on
-- recipe_id (via the partial unique index), so re-running after editing
-- recipes.json refreshes the seeded post's title/description/tags/etc.
-- Run this once in the SQL Editor, after schema.sql.

on conflict (recipe_id) where recipe_id is not null do update set
  photo_url = excluded.photo_url,
  title = excluded.title,
  description = excluded.description,
  ingredient_ids = excluded.ingredient_ids,
  tags = excluded.tags;
